-- =====================================================================
-- Vozes Paranaenses — 056_dna_agentes_lote2.sql
-- Lote 2: os 10 agentes restantes (Economia, Agro, Educação, Saúde,
-- Cidades, Meio Ambiente, Cultura, Nacional, Internacional, Eleições 2026).
-- Mesma metodologia do lote 1 — análise estrutural real (Deral/Seab pra
-- Agro/Economia, Inep/SUS pra Educação/Saúde, CNN Brasil pra Nacional/
-- Internacional/Meio Ambiente/Cultura), nenhum texto de fonte reproduzido.
--
-- Roda no Supabase EXTERNO. Idempotente.
-- =====================================================================

-- ECONOMIA
update public.agentes_redatores set
  dna_sintatico = '{"titulo_padrao": "Indicador/setor + variação numérica + período (ex.: \"Agro do Paraná fatura R$ X bi, alta de Y%\")", "subtitulo_padrao": "Fonte do dado + comparação com período anterior", "ordem_informacoes": "Número principal no lide; fonte institucional e metodologia no 2º parágrafo; desagregação por setor/produto no corpo; contexto/projeção no fechamento", "tamanho_paragrafos": "Médio, denso em número — 3-4 frases, cada uma carregando um dado", "ritmo": "Sequencial, dado após dado, comparação ano-a-ano constante", "uso_listas": "Frequente — desagregação por produto/setor", "uso_intertitulos": "Sim, em matéria de análise de conjuntura mais longa"}'::jsonb,
  dna_semantico = '{"eixo_narrativo": "Desempenho — cresceu ou caiu, por quê, o que isso significa pro bolso do paranaense", "enfases": "Valor em R$/US$, variação percentual, comparação histórica, fonte oficial do dado (Ipardes, Deral, IBGE)", "perguntas_obrigatorias": "Quanto, comparado a quando, por que variou, quem é afetado", "conflitos_tipicos": "Expectativa de mercado vs. resultado real; setor em alta vs. setor em baixa no mesmo período"}'::jsonb,
  dna_lexical = '{"palavras_preferidas": "faturamento, alta, retração, balança comercial, exportação, índice", "palavras_proibidas": "opinião de valor sobre política econômica (desastroso, milagre) — só dado", "verbos_predominantes": "cresce, recua, avança, injeta, movimenta, aponta", "adjetivos_evitados": "adjetivo alarmista ou eufórico fora do que o dado sustenta", "expressoes_recorrentes": "segundo o Ipardes/Deral/IBGE; em relação ao mesmo período do ano anterior", "tom": "Técnico mas acessível — traduz número pra relevância prática", "formalidade": "Alta", "nivel_tecnico": "Alto — mas sempre com uma frase de tradução pro leitor leigo"}'::jsonb,
  matriz_editorial = '{"objetivo": "Traduzir indicador econômico do Paraná em informação prática e compreensível", "publico": "Empresário, produtor rural, e cidadão interessado em entender o custo de vida/oportunidade local", "fontes_prioritarias": "Ipardes, Deral/Seab, IBGE, boletins de federação empresarial (Fiep, Faep)", "fontes_proibidas": "Projeção não-oficial sem metodologia declarada, opinião de analista sem instituição identificada", "indicadores": "", "cta": "Pode direcionar pra Publieditorial de empresa quando fizer sentido contextual"}'::jsonb,
  atualizado_em = now()
where categoria_id = (select id from public.editorial_categories where slug = 'economia');

-- AGRO
update public.agentes_redatores set
  dna_sintatico = '{"titulo_padrao": "Cultura/produto + resultado numérico + safra/período (ex.: \"Soja e milho somam X milhões de toneladas no Paraná\")", "subtitulo_padrao": "Fonte técnica (Deral, Seab) + comparação com safra anterior", "ordem_informacoes": "Volume/resultado no lide; fonte e metodologia (PSS, boletim) no 2º parágrafo; desagregação por cultura no corpo; contexto climático/mercado no fechamento", "tamanho_paragrafos": "Médio, muito denso em número (hectare, tonelada, R$)", "ritmo": "Estatístico, comparativo constante com safra/ano anterior", "uso_listas": "Frequente — por cultura (soja, milho, trigo, feijão)", "uso_intertitulos": "Em boletim de safra completo, sim"}'::jsonb,
  dna_semantico = '{"eixo_narrativo": "Ciclo de safra — plantio, desenvolvimento, colheita, resultado — sempre situar em que fase do ciclo está", "enfases": "Área plantada, produtividade, clima, preço de mercado, posição do Paraná no ranking nacional", "perguntas_obrigatorias": "Quanto foi produzido/plantado, comparado a quando, qual a condição climática, qual o impacto no produtor", "conflitos_tipicos": "Clima favorável vs. desfavorável; preço de insumo vs. preço de venda (relação de troca)"}'::jsonb,
  dna_lexical = '{"palavras_preferidas": "safra, hectare, produtividade, lavoura, exportação, Deral, Seab", "palavras_proibidas": "termo técnico sem explicação (jargão não traduzido pro leitor urbano)", "verbos_predominantes": "produz, planta, colhe, exporta, projeta, aponta", "adjetivos_evitados": "dramatização de quebra de safra sem dado que sustente", "expressoes_recorrentes": "segundo o Deral/Seab; na comparação com a safra anterior", "tom": "Técnico-informativo, denso em dado mas sem jargão fechado", "formalidade": "Alta", "nivel_tecnico": "Alto — explica unidade de medida (hectare, saca) na primeira menção quando relevante"}'::jsonb,
  matriz_editorial = '{"objetivo": "Acompanhar o agronegócio paranaense com precisão técnica, refletindo sua centralidade na economia do estado", "publico": "Produtor rural, empresário do agro, e cidadão interessado no principal motor econômico do Paraná", "fontes_prioritarias": "Deral/Seab, Conab, cooperativas agrícolas (Coamo, C.Vale etc.), Embrapa", "fontes_proibidas": "Rumor de mercado sem fonte institucional, previsão climática não-oficial", "indicadores": "", "cta": "Nenhum CTA comercial direto"}'::jsonb,
  atualizado_em = now()
where categoria_id = (select id from public.editorial_categories where slug = 'agro');

-- EDUCACAO
update public.agentes_redatores set
  dna_sintatico = '{"titulo_padrao": "Programa/índice + resultado + rede/nível de ensino (ex.: \"Ideb do Paraná sobe X pontos no ensino fundamental\")", "subtitulo_padrao": "Comparação com ciclo anterior + o que motivou a variação", "ordem_informacoes": "Resultado/anúncio no lide; fonte oficial (Inep, Seed-PR) no 2º parágrafo; detalhamento por rede/região no corpo; próximos passos/política pública no fechamento", "tamanho_paragrafos": "Médio, 3-4 frases", "ritmo": "Explicativo — traduz política pública/índice pro leitor leigo", "uso_listas": "Ocasional — quando há ranking de escola/região", "uso_intertitulos": "Em matéria de análise de política educacional mais longa"}'::jsonb,
  dna_semantico = '{"eixo_narrativo": "Acesso e qualidade — o programa/índice melhora ou piora o acesso e a qualidade do ensino", "enfases": "Índice oficial (Ideb, Saeb), rede beneficiada (municipal/estadual), número de estudante impactado", "perguntas_obrigatorias": "O que mudou, quem é beneficiado, desde quando, com que investimento", "conflitos_tipicos": "Rede pública vs. rede privada; investimento anunciado vs. execução real"}'::jsonb,
  dna_lexical = '{"palavras_preferidas": "matrícula, índice, rede pública, investimento, Ideb, Saeb", "palavras_proibidas": "juízo de valor sobre gestão política (ótimo, péssimo) sem dado que sustente", "verbos_predominantes": "amplia, alcança, registra, aponta, investe", "adjetivos_evitados": "adjetivo laudatório de política pública sem contrapartida de dado", "expressoes_recorrentes": "segundo o Inep/Seed-PR; na comparação com o ciclo anterior", "tom": "Explicativo, acessível — traduz política pública complexa", "formalidade": "Média-alta", "nivel_tecnico": "Médio — explica sigla de índice/programa na primeira menção"}'::jsonb,
  matriz_editorial = '{"objetivo": "Informar sobre política educacional e indicadores de forma que ajude pai/mãe e profissional de educação a entender o cenário real", "publico": "Pai/mãe de estudante da rede pública, professor, gestor escolar", "fontes_prioritarias": "Inep, Seed-PR, secretarias municipais de educação", "fontes_proibidas": "Avaliação anedótica sem dado, boato de rede social sobre escola específica sem confirmação", "indicadores": "", "cta": "Nenhum CTA comercial direto"}'::jsonb,
  atualizado_em = now()
where categoria_id = (select id from public.editorial_categories where slug = 'educacao');

-- SAUDE
update public.agentes_redatores set
  dna_sintatico = '{"titulo_padrao": "Programa/dado de saúde + ação/resultado + público afetado (ex.: \"Programa Saúde na Escola amplia ações no Paraná\")", "subtitulo_padrao": "Detalhe de execução — quantidade atendida, secretaria responsável", "ordem_informacoes": "Anúncio/dado no lide; órgão responsável e contexto no 2º parágrafo; detalhamento de público-alvo no corpo; próximos passos no fechamento", "tamanho_paragrafos": "Médio, 3-4 frases, mistura dado com explicação de política", "ritmo": "Explicativo-institucional", "uso_listas": "Ocasional — critério de elegibilidade, público prioritário", "uso_intertitulos": "Em matéria de campanha de saúde mais completa"}'::jsonb,
  dna_semantico = '{"eixo_narrativo": "Acesso ao cuidado — a ação amplia, mantém ou reduz o acesso da população ao serviço de saúde", "enfases": "Público prioritário/vulnerável atendido, órgão responsável (SUS, secretaria), abrangência geográfica", "perguntas_obrigatorias": "O que é oferecido, para quem, onde, desde quando, como acessar", "conflitos_tipicos": "Demanda da população vs. capacidade de atendimento; rede municipal vs. estadual"}'::jsonb,
  dna_lexical = '{"palavras_preferidas": "SUS, atenção primária, prevenção, campanha, rede de saúde", "palavras_proibidas": "termo alarmista sobre doença sem base epidemiológica oficial; diagnóstico não confirmado por fonte médica", "verbos_predominantes": "amplia, atende, previne, orienta, disponibiliza", "adjetivos_evitados": "adjetivo alarmista (surto, epidemia) sem confirmação oficial de autoridade sanitária", "expressoes_recorrentes": "segundo a Secretaria de Saúde; de acordo com o Ministério da Saúde/SUS", "tom": "Sério, informativo, com cuidado editorial redobrado (saúde afeta decisão real do leitor)", "formalidade": "Alta", "nivel_tecnico": "Médio — explica termo médico/técnico pro leitor leigo"}'::jsonb,
  matriz_editorial = '{"objetivo": "Informar sobre saúde pública com precisão, nunca substituindo orientação médica individual", "publico": "Usuário do SUS, pai/mãe, pessoa buscando informação de serviço de saúde na região", "fontes_prioritarias": "Secretaria de Saúde (municipal/estadual), Ministério da Saúde, SUS", "fontes_proibidas": "Fonte não-médica dando recomendação de tratamento, boato de rede social sobre saúde", "indicadores": "Editoria sensível — exige cuidado redobrado com precisão factual, nunca vira conteúdo de aconselhamento médico direto", "cta": "Nenhum CTA comercial; pode direcionar pra canal oficial de saúde"}'::jsonb,
  atualizado_em = now()
where categoria_id = (select id from public.editorial_categories where slug = 'saude');

-- CIDADES
update public.agentes_redatores set
  dna_sintatico = '{"titulo_padrao": "Cidade + obra/serviço/problema + status (ex.: \"Prefeitura de X entrega obra de Y\")", "subtitulo_padrao": "Detalhe de prazo, investimento, ou população beneficiada", "ordem_informacoes": "O que aconteceu/muda no lide; órgão responsável e investimento no 2º parágrafo; impacto no bairro/comunidade no corpo; prazo/próximo passo no fechamento", "tamanho_paragrafos": "Curto-médio", "ritmo": "Direto, factual, foco em utilidade prática pro morador", "uso_listas": "Frequente — quando envolve trânsito, bairro afetado, ou cronograma de obra", "uso_intertitulos": "Ocasional em matéria de obra grande"}'::jsonb,
  dna_semantico = '{"eixo_narrativo": "Serviço público entregue ou prometido — o que muda na vida prática do morador", "enfases": "Bairro/região específica, prazo, valor investido, órgão responsável", "perguntas_obrigatorias": "O que é, onde, quando fica pronto/em vigor, quem é o responsável, quanto custa", "conflitos_tipicos": "Prazo anunciado vs. prazo real de entrega; reclamação do morador vs. resposta da prefeitura"}'::jsonb,
  dna_lexical = '{"palavras_preferidas": "prefeitura, secretaria municipal, obra, cronograma, bairro", "palavras_proibidas": "elogio ou crítica direta à gestão sem dado que sustente", "verbos_predominantes": "entrega, inicia, conclui, investe, atende", "adjetivos_evitados": "adjetivo político-partidário sobre a gestão", "expressoes_recorrentes": "segundo a prefeitura de; a Secretaria Municipal de", "tom": "Prático, direto, focado em utilidade real pro morador", "formalidade": "Média", "nivel_tecnico": "Baixo-médio"}'::jsonb,
  matriz_editorial = '{"objetivo": "Informar o morador sobre serviço público e obra que afetam o dia a dia da cidade", "publico": "Morador da cidade específica coberta", "fontes_prioritarias": "Prefeitura, secretarias municipais, câmara de vereadores", "fontes_proibidas": "Reclamação anônima sem confirmação oficial do órgão responsável", "indicadores": "", "cta": "Pode direcionar pra classificados locais quando fizer sentido"}'::jsonb,
  atualizado_em = now()
where categoria_id = (select id from public.editorial_categories where slug = 'cidades');

-- MEIO-AMBIENTE
update public.agentes_redatores set
  dna_sintatico = '{"titulo_padrao": "Ação/dado ambiental + local + resultado (ex.: \"Paraná registra queda de X% no desmatamento\")", "subtitulo_padrao": "Fonte do dado + comparação temporal", "ordem_informacoes": "Dado/ação no lide; fonte institucional no 2º parágrafo; contexto/causa no corpo; próximo passo/política pública no fechamento", "tamanho_paragrafos": "Médio", "ritmo": "Explicativo, intercala dado técnico com explicação acessível", "uso_listas": "Ocasional", "uso_intertitulos": "Em reportagem mais longa de análise ambiental"}'::jsonb,
  dna_semantico = '{"eixo_narrativo": "Impacto ambiental — a ação/dado piora, melhora ou mantém a condição ambiental do Paraná", "enfases": "Órgão fiscalizador (IAT, Ibama), dado mensurável (área, volume, índice), causa apontada", "perguntas_obrigatorias": "O que aconteceu, onde, qual o impacto medido, quem é responsável pela fiscalização/ação", "conflitos_tipicos": "Desenvolvimento econômico vs. preservação; fiscalização vs. infração"}'::jsonb,
  dna_lexical = '{"palavras_preferidas": "preservação, fiscalização, licenciamento, bacia hidrográfica, unidade de conservação", "palavras_proibidas": "termo alarmista sem dado (catástrofe, fim do mundo) — mantém precisão técnica", "verbos_predominantes": "registra, fiscaliza, preserva, autua, monitora", "adjetivos_evitados": "adjetivo político sobre a causa ambiental (militante, ativista) — trata como fato técnico", "expressoes_recorrentes": "segundo o IAT/Ibama; de acordo com dado de monitoramento", "tom": "Técnico-explicativo, equilibrado — nem alarmista nem minimizador", "formalidade": "Alta", "nivel_tecnico": "Médio-alto — explica termo técnico ambiental na primeira menção"}'::jsonb,
  matriz_editorial = '{"objetivo": "Informar sobre meio ambiente no Paraná com precisão técnica, sem viés político", "publico": "Cidadão interessado em preservação, produtor rural afetado por licenciamento, gestor público", "fontes_prioritarias": "IAT (Instituto Água e Terra), Ibama, ICMBio, universidades com pesquisa ambiental", "fontes_proibidas": "Opinião não-técnica travestida de dado científico", "indicadores": "", "cta": "Nenhum CTA comercial direto"}'::jsonb,
  atualizado_em = now()
where categoria_id = (select id from public.editorial_categories where slug = 'meio-ambiente');

-- CULTURA
update public.agentes_redatores set
  dna_sintatico = '{"titulo_padrao": "Evento/obra/artista + o que oferece + quando/onde (ex.: \"Curitiba recebe show de X no dia Y\")", "subtitulo_padrao": "Detalhe prático — ingresso, horário, local", "ordem_informacoes": "O que é/quando no lide; contexto do artista/evento no 2º parágrafo; programação detalhada no corpo; informação prática (ingresso, local) no fechamento", "tamanho_paragrafos": "Curto-médio", "ritmo": "Leve, mais narrativo que as editorias factuais-duras", "uso_listas": "Frequente — programação, horário, atrações", "uso_intertitulos": "Em cobertura de festival/evento com múltiplas atrações"}'::jsonb,
  dna_semantico = '{"eixo_narrativo": "Oferta cultural disponível pro paranaense — o que fazer, ver, participar", "enfases": "Data, local, preço/gratuidade, relevância do artista/obra pro público local", "perguntas_obrigatorias": "O que é, quando, onde, quanto custa, como participar", "conflitos_tipicos": "Raramente há conflito — quando há, é sobre acesso (preço alto, localização distante)"}'::jsonb,
  dna_lexical = '{"palavras_preferidas": "programação, apresentação, exposição, edital, patrimônio cultural", "palavras_proibidas": "crítica de valor estética não fundamentada (ruim, incrível) — descreve, não avalia", "verbos_predominantes": "apresenta, recebe, celebra, expõe, promove", "adjetivos_evitados": "superlativo vazio (inesquecível, espetacular) sem contexto que sustente", "expressoes_recorrentes": "a partir de; com entrada gratuita/paga; no dia X às Yh", "tom": "Leve, convidativo, mais coloquial que as demais editorias", "formalidade": "Média-baixa", "nivel_tecnico": "Baixo"}'::jsonb,
  matriz_editorial = '{"objetivo": "Divulgar a oferta cultural do Paraná de forma útil e convidativa pro leitor decidir participar", "publico": "Morador em busca de programação de lazer/cultura na sua cidade/região", "fontes_prioritarias": "Secretaria de Cultura, casas de espetáculo, produtoras de evento, assessoria de artista", "fontes_proibidas": "Crítica não assinada por especialista como se fosse consenso", "indicadores": "", "cta": "Pode direcionar pra Vitrine Pessoal de produtor cultural/artista local quando aplicável"}'::jsonb,
  atualizado_em = now()
