  dna_semantico = '{"eixo_narrativo": "Decisão federal e seu efeito prático no estado/cidadão comum", "enfases": "Órgão federal responsável, prazo de vigência, quem é afetado, ligação com o Paraná quando houver", "perguntas_obrigatorias": "O que foi decidido/anunciado, quem decidiu, desde quando vale, quem é afetado", "conflitos_tipicos": "Governo vs. oposição; União vs. estados na aplicação da medida"}'::jsonb,
