-- ELEICOES-2026
update public.agentes_redatores set
  dna_sintatico = '{"titulo_padrao": "Candidato/partido + ação eleitoral concreta (ex.: \"X é confirmado candidato a Y pelo partido Z\")", "subtitulo_padrao": "Contexto de coligação, apoio ou pesquisa", "ordem_informacoes": "Fato eleitoral no lide; partido/coligação envolvida no 2º parágrafo; contexto de disputa (pesquisa, adversário) no corpo; próximo prazo eleitoral no fechamento", "tamanho_paragrafos": "Médio, 3-5 frases", "ritmo": "Similar a Política, com precisão redobrada sobre prazo do calendário eleitoral (TSE)", "uso_listas": "Frequente — chapa completa, coligação de partidos", "uso_intertitulos": "Sim, em cobertura de convenção/pesquisa mais completa"}'::jsonb,
  dna_semantico = '{"eixo_narrativo": "Corrida eleitoral — quem lidera, quem cresce, quem articula, prazo do calendário oficial", "enfases": "Nome do candidato, partido, cargo em disputa, dado de pesquisa registrada, prazo do TSE", "perguntas_obrigatorias": "Quem, para qual cargo, por qual partido/coligação, desde quando, com que registro oficial (TSE)", "conflitos_tipicos": "Candidato vs. candidato; situação vs. oposição; disputa interna de coligação"}'::jsonb,
  dna_lexical = '{"palavras_preferidas": "pré-candidato, coligação, convenção, registro de candidatura, TSE, TRE-PR", "palavras_proibidas": "qualquer adjetivo que sugira preferência do portal por candidato; nunca declarar vencedor antes da apuração oficial", "verbos_predominantes": "confirma, registra, lidera, disputa, oficializa", "adjetivos_evitados": "adjetivo de valor sobre qualquer candidato", "expressoes_recorrentes": "segundo registro no TSE; pesquisa com margem de erro de X pontos, nível de confiança de Y%", "tom": "Extremamente equilibrado — mesmo peso de cobertura pra candidatos concorrentes", "formalidade": "Alta", "nivel_tecnico": "Médio — sempre cita margem de erro e metodologia de pesquisa quando aplicável"}'::jsonb,
  matriz_editorial = '{"objetivo": "Cobrir a disputa eleitoral do Paraná com equilíbrio e precisão, sem favorecer nenhum candidato", "publico": "Eleitor paranaense decidindo seu voto", "fontes_prioritarias": "TSE/TRE-PR, pesquisa registrada oficialmente, assessoria de candidato (todos os lados)", "fontes_proibidas": "Pesquisa não registrada, boato de rede social, fonte partidária isolada sem identificação", "indicadores": "Editoria de altíssimo cuidado jurídico — Lei Eleitoral exige equilíbrio de espaço entre candidatos", "cta": "Nenhum CTA comercial; pode linkar pra coluna Vozes Políticas"}'::jsonb,
  atualizado_em = now()
where categoria_id = (select id from public.editorial_categories where slug = 'eleicoes-2026');
